        if (n <= 0) {
            return false;
        }

        // Convert n to a BigDecimal to avoid integer overflow
        BigDecimal bigN = valueOf(n);
        int exponent = (int) (math.log10(bigN) / math.log10(3));

        // Check if n is a power of three by checking if exponent is an integer
        return bigN.doubleValue() == Math.pow(3, exponent) && exponent % 1 == 0;
    }
}
```

